export function productExceptSelf(nums) {
    const result = Array(nums.length).fill(1);
    let p = 1;
    for (let i = 0; i < nums.length; i++) {
        result[i] = p;
        p *= nums[i];
    }
    p = 1;
    for (let i = nums.length - 1; i >= 0; i--) {
        result[i] *= p;
        p *= nums[i];
    }
    return result;
}
